```typescript
import { EmployeeNode, RawRow, TreeData, ColumnMapping } from '../types';

export const parseCSV = (text: string, mapping?: ColumnMapping): RawRow[] => {
  const lines = text.split('\n').map((line) => line.trim()).filter((line) => line.length > 0);

  // If mapping is provided, we assume the first row was headers and has already been stripped or handled by the caller,
  // OR the caller passed the full text. 
  // For this implementation, we will assume the caller passes raw text (including headers if uploaded).
  // If mapping exists, we skip the first row (headers).

  const startIndex = mapping ? 1 : 0;

  return lines.slice(startIndex).map((line) => {
    const parts = line.split(',');
    if (mapping) {
      return {
        employee: parts[mapping.employee],
        manager: parts[mapping.manager],
        designation: parts[mapping.designation] || undefined,
        grade: parts[mapping.grade] || undefined,
      } as RawRow | null;
    } else {
      return {
        employee: parts[0],
        manager: parts[1],
      } as RawRow | null;
    }
  }).filter((row): row is RawRow => row !== null);
};

export const createTreeData = (rawData: RawRow[]): TreeData => {
  const treeData: TreeData = {};

  rawData.forEach((row) => {
    if (!row) {
        return
    }
    const { employee, manager, designation, grade } = row;

    if (!treeData[manager]) {
      treeData[manager] = {
        name: manager,
        designation: designation || '',
        grade: grade || '',
        children: [],
      };
    }

    if (employee) {
      treeData[employee] = {
        name: employee,
        designation: designation || '',
        grade: grade || '',
        children: [],
      };
      treeData[manager].children.push(treeData[employee]);
    }
  });

  return treeData;
};

export const processCSVToXML = (csvText: string, mapping?: ColumnMapping): string => {
  const rawData = parseCSV(csvText, mapping);
  const treeData = createTreeData(rawData);

  let xml = '<?xml version="1.0" encoding="UTF-8"?>\n<Organization>\n';
  xml += generateXmlFromTree(treeData);
  xml += '</Organization>';
  return xml;
};

const generateXmlFromTree = (treeData: TreeData, parentKey: string = 'root', indent: string = ''): string => {
  let xml = '';
  const node = treeData[parentKey];
  if (node) {
    xml += `${indent}<Employee name="${node.name}" designation="${node.designation}" grade="${node.grade}">\n`;
    node.children.forEach((child) => {
      xml += generateXmlFromTree(treeData, child.name, indent + '  ');
    });
    xml += `${indent}</Employee>\n`;
  } else {
    // Handle the case where the parent node doesn't exist. This can happen for the root node or if data is inconsistent.
    // In a real-world scenario, you might log this, throw an error, or handle it in some other way.
    // For this example, we'll just ignore it.
  }
  return xml;
