import React, { useState, useMemo } from 'react';
import { TreeData, EmployeeNode } from '../types';
import { ChevronDown, ChevronRight, User, Users, Search, X, Filter } from 'lucide-react';

interface OrgTreeProps {
  data: TreeData[];
  allNodes: EmployeeNode[];
}

const TreeNode: React.FC<{ nodeData: TreeData; depth: number }> = ({ nodeData, depth }) => {
  const [isOpen, setIsOpen] = useState(true);
  const hasChildren = nodeData.children.length > 0;
  const { node } = nodeData;

  const displayLabel = () => {
    // Priority: Name > ID
    let label = node.name || node.id;

    // Add extras
    const extras = [];
    if (node.name) extras.push(node.id); // Show ID if Name is primary
    if (node.grade) extras.push(node.grade);
    if (node.designation) extras.push(node.designation);

    return { main: label, sub: extras.join(' • ') };
  };

  const { main, sub } = displayLabel();

  return (
    <div className="select-none">
      <div 
        className={`
          flex items-center py-2 px-3 rounded-lg cursor-pointer transition-colors
          ${depth === 0 ? 'bg-indigo-50 mb-1 border border-indigo-100' : 'hover:bg-slate-50'}
        `}
        style={{ marginLeft: `${depth * 24}px` }}
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="flex items-center justify-center w-5 h-5 mr-1 text-slate-400">
          {hasChildren && (
            isOpen ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />
          )}
        </div>

        <div className={`p-1.5 rounded-full mr-3 ${depth === 0 ? 'bg-indigo-200 text-indigo-700' : 'bg-slate-200 text-slate-600'}`}>
          {depth === 0 ? <Users className="w-4 h-4" /> : <User className="w-4 h-4" />}
        </div>

        <div className="flex flex-col">
          <span className={`text-sm ${depth === 0 ? 'font-bold text-indigo-900' : 'font-medium text-slate-700'}`}>
            {main}
          </span>
          <span className="text-xs text-slate-500">
             Level {nodeData.node.level} {sub && ` • ${sub}`}
          </span>
        </div>
      </div>

      {isOpen && hasChildren && (
        <div className="border-l border-slate-200 ml-[1.65rem] pl-1">
          {nodeData.children.map((child) => (
            <TreeNode key={child.id} nodeData={child} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
};

const OrgTree: React.FC<OrgTreeProps> = ({ data, allNodes }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredRootId, setFilteredRootId] = useState<string | null>(null);

  // Helper to find a specific node in the recursive structure
  const findSubtree = (nodes: TreeData[], targetId: string): TreeData | null => {
    for (const node of nodes) {
      if (node.id === targetId) return node;
      if (node.children.length > 0) {
        const found = findSubtree(node.children, targetId);
        if (found) return found;
      }
    }
    return null;
  };

  // Determine what to display: Full tree or Filtered Subtree
  const displayData = useMemo(() => {
    if (!filteredRootId) return data;
    const found = findSubtree(data, filteredRootId);
    // If found, return as an array (since OrgTree iterates over a list of roots)
    return found ? [found] : [];
  }, [data, filteredRootId]);

  // Suggestions for autocomplete
  const suggestions = useMemo(() => {
    if (!searchTerm) return [];
    return allNodes
      .filter(n => 
        n.id.toLowerCase().includes(searchTerm.toLowerCase()) || 
        (n.name && n.name.toLowerCase().includes(searchTerm.toLowerCase()))
      )
      .slice(0, 10);
  }, [searchTerm, allNodes]);

  const handleFilter = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;

    // Check if valid ID or Name match
    const foundNode = allNodes.find(n => n.id === searchTerm || n.name === searchTerm);

    if (foundNode) {
      setFilteredRootId(foundNode.id);
    } else {
        // Fallback for typed ID
         const isValid = allNodes.some(n => n.id === searchTerm);
         if (isValid) setFilteredRootId(searchTerm);
    }
  };

  const handleClear = () => {
    setSearchTerm('');
    setFilteredRootId(null);
  };

  if (allNodes.length === 0) return null;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      {/* Header with Filter Controls */}
      <div className="p-4 border-b border-slate-200 bg-slate-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h3 className="font-semibold text-slate-700 flex items-center gap-2">
            <Users className="w-5 h-5 text-indigo-600" />
            Hierarchy Visualization
          </h3>
          <p className="text-sm text-slate-500">
             {filteredRootId ? `Viewing subtree for ${filteredRootId}` : 'Viewing full organization structure'}
          </p>
        </div>

        <form onSubmit={handleFilter} className="flex items-center gap-2 w-full sm:w-auto">
           <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input
              type="text"
              list="tree-employees"
              placeholder="Filter by name or ID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-8 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <datalist id="tree-employees">
              {suggestions.map(node => (
                <option key={node.id} value={node.name || node.id} />
              ))}
            </datalist>

            {searchTerm && (
              <button 
                type="button"
                onClick={() => setSearchTerm('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
              >
                <X className="w-4 h-4" />
              </button>
            )}
           </div>

           {filteredRootId ? (
             <button
                type="button"
                onClick={handleClear}
                className="px-3 py-2 bg-white border border-slate-300 text-slate-700 text-sm font-medium rounded-lg hover:bg-slate-50 transition-colors flex items-center gap-2"
             >
                <X className="w-4 h-4" />
                Reset
             </button>
           ) : (
             <button
                type="submit"
                disabled={!searchTerm}
                className="px-3 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
             >
                <Filter className="w-4 h-4" />
                Filter
             </button>
           )}
        </form>
      </div>

      {/* Tree Content */}
      <div className="p-6 h-full overflow-auto flex-1">
        {displayData.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-400">
             <Search className="w-12 h-12 mb-2 opacity-20" />
             <p>No matches found in the hierarchy.</p>
             <button onClick={handleClear} className="mt-4 text-indigo-600 hover:underline text-sm">
               Show full tree
             </button>
          </div>
        ) : (
          <div className="space-y-2">
            {displayData.map((root) => (
              <TreeNode key={root.id} nodeData={root} depth={0} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default OrgTree;

import React, { useState, useRef, useMemo } from 'react';
import mermaid from 'mermaid';
import { EmployeeNode } from '../types';
import { Search, Network, Loader2, AlertCircle, Layers, Settings2, ZoomIn, ZoomOut, RotateCcw, Move, Maximize, Minimize } from 'lucide-react';

interface MermaidChartProps {
  nodes: EmployeeNode[];
}

mermaid.initialize({
  startOnLoad: false,
  theme: 'base',
  securityLevel: 'loose',
  themeVariables: {
    primaryColor: '#e0e7ff',
    primaryTextColor: '#1e1b4b',
    primaryBorderColor: '#4338ca',
    lineColor: '#64748b',
    secondaryColor: '#f1f5f9',
    tertiaryColor: '#fff',
  },
});

const MermaidChart: React.FC<MermaidChartProps> = ({ nodes }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedRoot, setSelectedRoot] = useState<string>('');
  const [depthLimit, setDepthLimit] = useState<string>('all');

  // Display Options
  const [showDesignation, setShowDesignation] = useState(false);
  const [showGrade, setShowGrade] = useState(false);

  // Chart State
  const [svgContent, setSvgContent] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Pan & Zoom State
  const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef({ x: 0, y: 0 });

  // Full Screen State
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const [isFullScreen, setIsFullScreen] = useState(false);

  // Create a map for quick access
  const nodeMap = useMemo(() => new Map(nodes.map(n => [n.id, n])), [nodes]);

  // Filter for datalist
  const suggestions = useMemo(() => {
    if (!searchTerm) return [];
    return nodes
      .filter(n => 
        n.id.toLowerCase().includes(searchTerm.toLowerCase()) || 
        (n.name && n.name.toLowerCase().includes(searchTerm.toLowerCase()))
      )
      .slice(0, 10);
  }, [searchTerm, nodes]);

  const generateChart = async (rootId: string) => {
    if (!rootId) return;

    setLoading(true);
    setError(null);
    setSvgContent('');
    // Reset view when regenerating
    setTransform({ x: 0, y: 0, scale: 1 });

    try {
      if (!nodeMap.has(rootId)) {
        throw new Error("Employee not found in the dataset.");
      }

      // 1. Setup Internal ID Map to avoid syntax errors with special chars in emails
      const idMap = new Map<string, string>();
      let idCounter = 0;
      const getNodeId = (email: string) => {
        if (!idMap.has(email)) {
          idMap.set(email, `N${idCounter++}`);
        }
        return idMap.get(email)!;
      };

      // 2. Traverse Graph
      const edges: string[] = [];
      const queue = [{ id: rootId, depth: 0 }];
      const visited = new Set<string>();
      visited.add(rootId);

      const MAX_NODES = 150; 
      let nodeCount = 0;

      while (queue.length > 0 && nodeCount < MAX_NODES) {
        const { id: currentId, depth } = queue.shift()!;

        const limit = depthLimit === 'all' ? Infinity : parseInt(depthLimit, 10);

        if (depth >= limit) {
          continue;
        }

        nodeCount++;
        const node = nodeMap.get(currentId);

        if (node && node.directReports.length > 0) {
          const sortedReports = [...node.directReports].sort();
          sortedReports.forEach(childId => {
            const parentNodeId = getNodeId(currentId);
            const childNodeId = getNodeId(childId);

            edges.push(`${parentNodeId} --> ${childNodeId}`);

            if (!visited.has(childId)) {
              visited.add(childId);
              queue.push({ id: childId, depth: depth + 1 });
            }
          });
        }
      }

      // 3. Build Definition String
      let graphDefinition = 'graph TD\n';

      visited.forEach(email => {
        const nodeId = getNodeId(email);
        const node = nodeMap.get(email);

        // Use Name if available, otherwise email
        let label = node?.name || email;

        if (node) {
            const extras: string[] = [];

            if (showDesignation && node.designation) {
              extras.push(node.designation);
            }
            if (showGrade && node.grade) {
              extras.push(node.grade);
            }

            if (extras.length > 0) {
              label += `<br/>${extras.join(', ')}`;
            }
        }

        // Sanitize label for Mermaid
        const safeLabel = label.replace(/"/g, "'"); 
        graphDefinition += `  ${nodeId}["${safeLabel}"]\n`;
      });

      edges.forEach(edge => {
        graphDefinition += `  ${edge}\n`;
      });

      graphDefinition += '\n  %% Styles\n';
      graphDefinition += '  classDef rootNode fill:#4f46e5,stroke:#312e81,stroke-width:2px,color:#fff;\n';

      const rootNodeId = getNodeId(rootId);
      graphDefinition += `  class ${rootNodeId} rootNode;\n`;

      if (nodeCount >= MAX_NODES) {
        setError(`Graph truncated: Exceeded maximum displayable nodes (${MAX_NODES}).`);
      }

      // 4. Render
      const id = `mermaid-${Date.now()}`;
      const { svg } = await mermaid.render(id, graphDefinition);
      setSvgContent(svg);

    } catch (err: any) {
      console.error(err);
      let msg = err.message || "Failed to render chart.";
      if (msg.includes("Parse error")) {
        msg = "Visual generation failed due to a syntax error. Please check for special characters in the data.";
      }
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedRoot) {
      generateChart(selectedRoot);
    }
  };

  const toggleFullScreen = () => {
    if (!chartContainerRef.current) return;

    if (!document.fullscreenElement) {
        chartContainerRef.current.requestFullscreen().then(() => {
            setIsFullScreen(true);
        }).catch(err => {
            console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
    } else {
        document.exitFullscreen().then(() => {
            setIsFullScreen(false);
        });
    }
  };

  // Sync state if user presses Esc
  React.useEffect(() => {
      const handleFSChange = () => {
          setIsFullScreen(!!document.fullscreenElement);
      };
      document.addEventListener('fullscreenchange', handleFSChange);
      return () => document.removeEventListener('fullscreenchange', handleFSChange);
  }, []);

  // --- Zoom & Pan Handlers ---

  const handleWheel = (e: React.WheelEvent) => {
    if (!svgContent) return;
    const scaleFactor = 0.001;
    const newScale = Math.min(Math.max(0.1, transform.scale - e.deltaY * scaleFactor), 5);
    setTransform(prev => ({ ...prev, scale: newScale }));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!svgContent) return;
    setIsDragging(true);
    dragStartRef.current = { 
      x: e.clientX - transform.x, 
      y: e.clientY - transform.y 
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setTransform(prev => ({
      ...prev,
      x: e.clientX - dragStartRef.current.x,
      y: e.clientY - dragStartRef.current.y
    }));
  };

  const handleMouseUp = () => setIsDragging(false);

  const zoomIn = () => setTransform(prev => ({ ...prev, scale: Math.min(prev.scale + 0.2, 5) }));
  const zoomOut = () => setTransform(prev => ({ ...prev, scale: Math.max(prev.scale - 0.2, 0.1) }));
  const resetView = () => setTransform({ x: 0, y: 0, scale: 1 });

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      {/* Controls Header */}
      <div className="p-4 border-b border-slate-200 bg-slate-50 flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center z-10">
        <div className="mb-2 xl:mb-0">
          <h3 className="font-semibold text-slate-700 flex items-center gap-2">
            <Network className="w-5 h-5 text-indigo-600" />
            Dynamic Org Chart
          </h3>
          <p className="text-sm text-slate-500">Visualize reporting lines for a specific employee</p>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row flex-wrap gap-3 w-full xl:w-auto items-end sm:items-center">

          <div className="flex items-center gap-3 bg-white px-3 py-2 rounded-lg border border-slate-200 mr-2 shadow-sm">
            <Settings2 className="w-4 h-4 text-slate-400" />
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer select-none">
              <input 
                type="checkbox" 
                checked={showDesignation} 
                onChange={(e) => setShowDesignation(e.target.checked)}
                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4" 
              />
              Designation
            </label>
            <div className="w-px h-4 bg-slate-200 mx-1"></div>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer select-none">
              <input 
                type="checkbox" 
                checked={showGrade} 
                onChange={(e) => setShowGrade(e.target.checked)}
                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4" 
              />
              Grade
            </label>
          </div>

          <div className="flex items-center gap-2 border border-slate-300 rounded-lg px-2 bg-white h-[38px]">
            <Layers className="w-4 h-4 text-slate-400" />
            <select
              value={depthLimit}
              onChange={(e) => setDepthLimit(e.target.value)}
              className="text-sm bg-transparent focus:outline-none text-slate-700 cursor-pointer pr-2"
            >
              <option value="all">All Layers</option>
              <option value="1">1 Layer</option>
              <option value="2">2 Layers</option>
              <option value="3">3 Layers</option>
              <option value="4">4 Layers</option>
              <option value="5">5 Layers</option>
            </select>
          </div>

          <div className="flex gap-2 w-full sm:w-auto">
            <div className="relative flex-1 sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input
                type="text"
                list="employees"
                placeholder="Name or Email..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  // Auto-select if matches exact ID
                  if (nodeMap.has(e.target.value)) {
                      setSelectedRoot(e.target.value);
                  }
                }}
                onBlur={() => {
                    if (nodeMap.has(searchTerm)) {
                        setSelectedRoot(searchTerm);
                    } else {
                        // Attempt to find ID by Name if user typed name
                        const found = nodes.find(n => n.name === searchTerm);
                        if (found) setSelectedRoot(found.id);
                    }
                }}
                className="w-full pl-9 pr-4 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 h-[38px]"
              />
              <datalist id="employees">
                {suggestions.map(node => (
                  <option key={node.id} value={node.name || node.id} />
                ))}
              </datalist>
            </div>
            <button
              type="submit"
              disabled={!selectedRoot || loading}
              className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors whitespace-nowrap h-[38px] flex items-center justify-center min-w-[80px]"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Build'}
            </button>
          </div>
        </form>
      </div>

      {/* Chart Display Area */}
      <div 
        ref={chartContainerRef}
        className={`flex-1 overflow-hidden bg-slate-50/50 relative flex flex-col items-center justify-center ${
            svgContent ? (isDragging ? 'cursor-grabbing' : 'cursor-grab') : ''
        }`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >

        {!svgContent && !loading && (
          <div className="text-center text-slate-400">
            <Network className="w-16 h-16 mx-auto mb-4 opacity-20" />
            <p>Select an employee and configure options above to generate their subtree.</p>
          </div>
        )}

        {loading && (
             <div className="flex flex-col items-center gap-3 text-indigo-600">
                <Loader2 className="w-8 h-8 animate-spin" />
                <span className="text-sm font-medium">Generating visualization...</span>
             </div>
        )}

        {error && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-amber-50 text-amber-700 px-4 py-2 rounded-lg border border-amber-200 text-sm flex items-center gap-2 shadow-sm z-10">
                <AlertCircle className="w-4 h-4" />
                {error}
            </div>
        )}

        {/* Rendered SVG Container */}
        {svgContent && (
            <div 
            style={{ 
                transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
                transformOrigin: 'center center',
                transition: isDragging ? 'none' : 'transform 0.1s ease-out'
            }}
            dangerouslySetInnerHTML={{ __html: svgContent }}
            />
        )}

        {/* Zoom Controls */}
        {svgContent && (
            <div className="absolute bottom-6 right-6 flex flex-col gap-2 bg-white p-1.5 rounded-lg shadow-lg border border-slate-200 z-20">
                <button 
                    onClick={zoomIn}
                    className="p-2 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    title="Zoom In"
                >
                    <ZoomIn className="w-5 h-5" />
                </button>
                <button 
                    onClick={zoomOut}
                    className="p-2 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    title="Zoom Out"
                >
                    <ZoomOut className="w-5 h-5" />
                </button>
                <div className="h-px bg-slate-200 my-0.5"></div>
                <button 
                    onClick={resetView}
                    className="p-2 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    title="Reset View"
                >
                    <RotateCcw className="w-5 h-5" />
                </button>
                <div className="h-px bg-slate-200 my-0.5"></div>
                <button 
                    onClick={toggleFullScreen}
                    className="p-2 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    title={isFullScreen ? "Exit Full Screen" : "Full Screen"}
                >
                    {isFullScreen ? <Minimize className="w-5 h-5" /> : <Maximize className="w-5 h-5" />}
                </button>
            </div>
        )}

        {/* Helper Hint */}
        {svgContent && (
            <div className="absolute bottom-6 left-6 bg-white/80 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 text-xs text-slate-500 shadow-sm pointer-events-none flex items-center gap-2">
                <Move className="w-3 h-3" />
                Scroll to zoom • Drag to pan
            </div>
        )}
      </div>
    </div>
  );
};

export default MermaidChart;

import React, { useState, useMemo } from 'react';
import { EmployeeNode } from '../types';
import { Search, AlertTriangle, ArrowRight, Download } from 'lucide-react';

interface OrgTableProps {
  nodes: EmployeeNode[];
}

const OrgTable: React.FC<OrgTableProps> = ({ nodes }) => {
  const [search, setSearch] = useState('');

  const filteredNodes = nodes.filter(
    (n) =>
      n.id.toLowerCase().includes(search.toLowerCase()) ||
      (n.name && n.name.toLowerCase().includes(search.toLowerCase())) ||
      n.rootId.toLowerCase().includes(search.toLowerCase()) ||
      (n.managerId && n.managerId.toLowerCase().includes(search.toLowerCase())) ||
      (n.designation && n.designation.toLowerCase().includes(search.toLowerCase()))
  );

  // Calculate the maximum depth to determine how many "Level X" columns to show
  const maxChainLength = useMemo(() => {
    return nodes.reduce((max, node) => Math.max(max, node.chain.length), 0);
  }, [nodes]);

  const levelColumns = useMemo(() => {
    return Array.from({ length: maxChainLength }, (_, i) => i);
  }, [maxChainLength]);

  const handleExport = () => {
    if (filteredNodes.length === 0) return;

    // Build Headers
    const staticHeaders = ['Level', 'Employee ID', 'Name', 'Grade', 'Designation', 'Direct Manager ID', 'Root ID', 'Has Cycle'];
    const dynamicHeaders = levelColumns.map(l => l === 0 ? 'Root (Level 0)' : `Level ${l}`);
    const headers = [...staticHeaders, ...dynamicHeaders];

    // Build Rows
    const csvRows = filteredNodes.map(node => {
      const staticData = [
        node.level,
        node.id,
        node.name || '',
        node.grade || '',
        node.designation || '',
        node.managerId || '',
        node.rootId,
        node.hasCycle ? 'Yes' : 'No'
      ];

      const dynamicData = levelColumns.map(level => {
        return node.chain[level] || '';
      });

      // Escape special characters for CSV
      return [...staticData, ...dynamicData].map(field => {
        const stringField = String(field);
        if (stringField.includes(',') || stringField.includes('"') || stringField.includes('\n')) {
          return `"${stringField.replace(/"/g, '""')}"`;
        }
        return stringField;
      }).join(',');
    });

    // Combine and Download
    const csvContent = [headers.join(','), ...csvRows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'org_structure_export.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (nodes.length === 0) return null;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      <div className="p-4 border-b border-slate-200 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-slate-50">
        <h3 className="font-semibold text-slate-700 flex items-center gap-2">
          Organization Roster
          <span className="px-2 py-0.5 rounded-full bg-slate-200 text-slate-600 text-xs font-bold">
            {nodes.length}
          </span>
        </h3>

        <div className="flex items-center gap-3 w-full sm:w-auto">
          <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input
              type="text"
              placeholder="Search..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-9 pr-4 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          <button
            onClick={handleExport}
            disabled={filteredNodes.length === 0}
            className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm whitespace-nowrap"
            title="Export filtered data to CSV"
          >
            <Download className="w-4 h-4" />
            <span className="hidden sm:inline">Export CSV</span>
          </button>
        </div>
      </div>

      <div className="overflow-auto flex-1">
        <table className="w-full text-left text-sm whitespace-nowrap">
          <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="px-6 py-3 font-semibold text-slate-600 border-b bg-slate-50 sticky left-0 z-20 shadow-[1px_0_0_0_rgba(0,0,0,0.05)] w-[80px]">
                Level
              </th>
              <th className="px-6 py-3 font-semibold text-slate-600 border-b bg-slate-50 sticky left-[80px] z-20 shadow-[1px_0_0_0_rgba(0,0,0,0.05)]">
                Employee ID
              </th>
              <th className="px-6 py-3 font-semibold text-slate-600 border-b">
                Name
              </th>
              <th className="px-6 py-3 font-semibold text-slate-600 border-b">
                Direct Manager
              </th>

              {/* Dynamic Columns for each Level */}
              {levelColumns.map((level) => (
                <th key={level} className="px-6 py-3 font-semibold text-indigo-900 border-b bg-indigo-50/30">
                  {level === 0 ? 'Root (Level 0)' : `Level ${level}`}
                </th>
              ))}

              <th className="px-6 py-3 font-semibold text-slate-600 border-b text-right">
                Visual Path
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredNodes.map((node) => (
              <tr key={node.id} className="hover:bg-slate-50 group">
                {/* Level Indicator */}
                <td className="px-6 py-3 bg-white group-hover:bg-slate-50 sticky left-0 z-10 shadow-[1px_0_0_0_rgba(0,0,0,0.05)]">
                   <span className={`inline-flex items-center justify-center w-8 h-8 rounded-full text-xs font-bold ${
                     node.level === 0 ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600'
                   }`}>
                     {node.hasCycle ? '!' : node.level}
                   </span>
                </td>

                {/* Employee ID */}
                <td className="px-6 py-3 font-medium text-slate-700 bg-white group-hover:bg-slate-50 sticky left-[80px] z-10 shadow-[1px_0_0_0_rgba(0,0,0,0.05)]">
                  <div className="flex flex-col">
                    <span>{node.id}</span>
                    {node.hasCycle && (
                      <span className="mt-1 inline-flex items-center text-red-500 text-xs">
                        <AlertTriangle className="w-3 h-3 mr-1" /> Cycle
                      </span>
                    )}
                  </div>
                </td>

                {/* Name */}
                <td className="px-6 py-3 text-slate-800">
                   {node.name || <span className="text-slate-300 italic">-</span>}
                </td>

                {/* Direct Manager */}
                <td className="px-6 py-3 text-slate-600">
                  {node.managerId || <span className="text-slate-300 italic">None</span>}
                </td>

                {/* Dynamic Level Cells */}
                {levelColumns.map((level) => {
                  const ancestorId = node.chain[level];
                  const isSelf = ancestorId === node.id;

                  return (
                    <td key={level} className="px-6 py-3 text-slate-600 border-l border-slate-50">
                      {ancestorId ? (
                        <span className={`
                          block truncate max-w-[180px] text-xs px-2 py-1 rounded
                          ${isSelf 
                            ? 'bg-indigo-100 text-indigo-700 font-medium' 
                            : 'text-slate-600'}
                        `} title={ancestorId}>
                          {ancestorId}
                        </span>
                      ) : (
                        <span className="text-slate-200 text-center block">-</span>
                      )}
                    </td>
                  );
                })}

                {/* Visual Summary */}
                <td className="px-6 py-3 text-right">
                  <div className="flex items-center justify-end gap-1 text-xs text-slate-400">
                    <span className="bg-slate-100 px-1.5 py-0.5 rounded text-slate-500">Root</span>
                    <ArrowRight className="w-3 h-3" />
                    <span className="bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded font-medium">Self</span>
                  </div>
                </td>
              </tr>
            ))}
            {filteredNodes.length === 0 && (
              <tr>
                <td colSpan={5 + levelColumns.length} className="px-6 py-8 text-center text-slate-500">
                  No employees found matching your search.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default OrgTable;

import React, { useState, useRef, useMemo } from 'react';
import mermaid from 'mermaid';
import { EmployeeNode } from '../types';
import { Search, Network, Loader2, AlertCircle, Layers, Settings2, ZoomIn, ZoomOut, RotateCcw, Move, Maximize, Minimize, LayoutTemplate } from 'lucide-react';

interface MermaidChartProps {
  nodes: EmployeeNode[];
}

mermaid.initialize({
  startOnLoad: false,
  theme: 'base',
  securityLevel: 'loose',
  themeVariables: {
    primaryColor: '#e0e7ff',
    primaryTextColor: '#1e1b4b',
    primaryBorderColor: '#4338ca',
    lineColor: '#64748b',
    secondaryColor: '#f1f5f9',
    tertiaryColor: '#fff',
  },
});

type ChartDirection = 'TD' | 'LR' | 'BT' | 'RL';
type CurveStyle = 'basis' | 'linear' | 'step';

const MermaidChart: React.FC<MermaidChartProps> = ({ nodes }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedRoot, setSelectedRoot] = useState<string>('');
  const [depthLimit, setDepthLimit] = useState<string>('all');

  // Display Options
  const [showDesignation, setShowDesignation] = useState(false);
  const [showGrade, setShowGrade] = useState(false);
  const [direction, setDirection] = useState<ChartDirection>('TD');
  const [curveStyle, setCurveStyle] = useState<CurveStyle>('basis');

  // Chart State
  const [svgContent, setSvgContent] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Pan & Zoom State
  const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef({ x: 0, y: 0 });

  // Full Screen State
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const [isFullScreen, setIsFullScreen] = useState(false);

  // Create a map for quick access
  const nodeMap = useMemo(() => new Map(nodes.map(n => [n.id, n])), [nodes]);

  // Filter for datalist - Prioritize ID search
  const suggestions = useMemo(() => {
    if (!searchTerm) return [];
    return nodes
      .filter(n => n.id.toLowerCase().includes(searchTerm.toLowerCase()))
      .slice(0, 10);
  }, [searchTerm, nodes]);

  const generateChart = async (rootId: string) => {
    if (!rootId) return;

    setLoading(true);
    setError(null);
    setSvgContent('');
    // Reset view when regenerating
    setTransform({ x: 0, y: 0, scale: 1 });

    try {
      if (!nodeMap.has(rootId)) {
        throw new Error("Employee not found in the dataset.");
      }

      // 1. Setup Internal ID Map to avoid syntax errors with special chars in emails
      const idMap = new Map<string, string>();
      let idCounter = 0;
      const getNodeId = (email: string) => {
        if (!idMap.has(email)) {
          idMap.set(email, `N${idCounter++}`);
        }
        return idMap.get(email)!;
      };

      // 2. Traverse Graph
      const edges: string[] = [];
      const queue = [{ id: rootId, depth: 0 }];
      const visited = new Set<string>();
      visited.add(rootId);

      const MAX_NODES = 150; 
      let nodeCount = 0;

      while (queue.length > 0 && nodeCount < MAX_NODES) {
        const { id: currentId, depth } = queue.shift()!;

        const limit = depthLimit === 'all' ? Infinity : parseInt(depthLimit, 10);

        if (depth >= limit) {
          continue;
        }

        nodeCount++;
        const node = nodeMap.get(currentId);

        if (node && node.directReports.length > 0) {
          const sortedReports = [...node.directReports].sort();
          sortedReports.forEach(childId => {
            const parentNodeId = getNodeId(currentId);
            const childNodeId = getNodeId(childId);

            edges.push(`${parentNodeId} --> ${childNodeId}`);

            if (!visited.has(childId)) {
              visited.add(childId);
              queue.push({ id: childId, depth: depth + 1 });
            }
          });
        }
      }

      // 3. Build Definition String
      // Inject Layout Options
      let graphDefinition = `graph ${direction}\n`;

      visited.forEach(email => {
        const nodeId = getNodeId(email);
        const node = nodeMap.get(email);

        // Use Name if available, otherwise email
        let label = node?.name || email;

        if (node) {
            const extras: string[] = [];

            if (showDesignation && node.designation) {
              extras.push(node.designation);
            }
            if (showGrade && node.grade) {
              // Wrap grade in parens as requested
              extras.push(`(${node.grade})`);
            }

            if (extras.length > 0) {
              label += `<br/>${extras.join(' ')}`;
            }
        }

        // Sanitize label for Mermaid
        const safeLabel = label.replace(/"/g, "'"); 
        graphDefinition += `  ${nodeId}["${safeLabel}"]\n`;
      });

      edges.forEach(edge => {
        graphDefinition += `  ${edge}\n`;
      });

      // Inject Curve Style
      if (curveStyle === 'step') {
         graphDefinition += `\n  linkStyle default interpolate stepAfter\n`;
      } else {
         graphDefinition += `\n  linkStyle default interpolate ${curveStyle}\n`;
      }

      graphDefinition += '\n  %% Styles\n';
      graphDefinition += '  classDef rootNode fill:#4f46e5,stroke:#312e81,stroke-width:2px,color:#fff;\n';

      const rootNodeId = getNodeId(rootId);
      graphDefinition += `  class ${rootNodeId} rootNode;\n`;

      if (nodeCount >= MAX_NODES) {
        setError(`Graph truncated: Exceeded maximum displayable nodes (${MAX_NODES}).`);
      }

      // 4. Render
      const id = `mermaid-${Date.now()}`;
      const { svg } = await mermaid.render(id, graphDefinition);
      setSvgContent(svg);

    } catch (err: any) {
      console.error(err);
      let msg = err.message || "Failed to render chart.";
      if (msg.includes("Parse error")) {
        msg = "Visual generation failed due to a syntax error. Please check for special characters in the data.";
      }
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedRoot) {
      generateChart(selectedRoot);
    }
  };

  const toggleFullScreen = () => {
    if (!chartContainerRef.current) return;

    if (!document.fullscreenElement) {
        chartContainerRef.current.requestFullscreen().then(() => {
            setIsFullScreen(true);
        }).catch(err => {
            console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
    } else {
        document.exitFullscreen().then(() => {
            setIsFullScreen(false);
        });
    }
  };

  // Sync state if user presses Esc
  React.useEffect(() => {
      const handleFSChange = () => {
          setIsFullScreen(!!document.fullscreenElement);
      };
      document.addEventListener('fullscreenchange', handleFSChange);
      return () => document.removeEventListener('fullscreenchange', handleFSChange);
  }, []);

  // --- Zoom & Pan Handlers ---

  const handleWheel = (e: React.WheelEvent) => {
    if (!svgContent) return;
    const scaleFactor = 0.001;
    const newScale = Math.min(Math.max(0.1, transform.scale - e.deltaY * scaleFactor), 5);
    setTransform(prev => ({ ...prev, scale: newScale }));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!svgContent) return;
    setIsDragging(true);
    dragStartRef.current = { 
      x: e.clientX - transform.x, 
      y: e.clientY - transform.y 
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setTransform(prev => ({
      ...prev,
      x: e.clientX - dragStartRef.current.x,
      y: e.clientY - dragStartRef.current.y
    }));
  };

  const handleMouseUp = () => setIsDragging(false);

  const zoomIn = () => setTransform(prev => ({ ...prev, scale: Math.min(prev.scale + 0.2, 5) }));
  const zoomOut = () => setTransform(prev => ({ ...prev, scale: Math.max(prev.scale - 0.2, 0.1) }));
  const resetView = () => setTransform({ x: 0, y: 0, scale: 1 });

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      {/* Controls Header */}
      <div className="p-4 border-b border-slate-200 bg-slate-50 flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center z-10">
        <div className="mb-2 xl:mb-0">
          <h3 className="font-semibold text-slate-700 flex items-center gap-2">
            <Network className="w-5 h-5 text-indigo-600" />
            Dynamic Org Chart
          </h3>
          <p className="text-sm text-slate-500">Visualize reporting lines for a specific employee</p>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row flex-wrap gap-3 w-full xl:w-auto items-end sm:items-center">

          <div className="flex items-center gap-3 bg-white px-3 py-2 rounded-lg border border-slate-200 mr-2 shadow-sm">
            <Settings2 className="w-4 h-4 text-slate-400" />
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer select-none">
              <input 
                type="checkbox" 
                checked={showDesignation} 
                onChange={(e) => setShowDesignation(e.target.checked)}
                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4" 
              />
              Designation
            </label>
            <div className="w-px h-4 bg-slate-200 mx-1"></div>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer select-none">
              <input 
                type="checkbox" 
                checked={showGrade} 
                onChange={(e) => setShowGrade(e.target.checked)}
                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4" 
              />
              Grade
            </label>
          </div>

          <div className="flex items-center gap-2 border border-slate-300 rounded-lg px-2 bg-white h-[38px]">
             <LayoutTemplate className="w-4 h-4 text-slate-400" />
             <select
               value={direction}
               onChange={(e) => setDirection(e.target.value as ChartDirection)}
               className="text-sm bg-transparent focus:outline-none text-slate-700 cursor-pointer pr-1"
               title="Chart Orientation"
             >
               <option value="TD">Top Down</option>
               <option value="LR">Left Right</option>
             </select>
             <div className="w-px h-4 bg-slate-200 mx-1"></div>
             <select
               value={curveStyle}
               onChange={(e) => setCurveStyle(e.target.value as CurveStyle)}
               className="text-sm bg-transparent focus:outline-none text-slate-700 cursor-pointer pr-1"
               title="Line Style"
             >
               <option value="basis">Curved</option>
               <option value="step">Step</option>
               <option value="linear">Straight</option>
             </select>
          </div>

          <div className="flex items-center gap-2 border border-slate-300 rounded-lg px-2 bg-white h-[38px]">
            <Layers className="w-4 h-4 text-slate-400" />
            <select
              value={depthLimit}
              onChange={(e) => setDepthLimit(e.target.value)}
              className="text-sm bg-transparent focus:outline-none text-slate-700 cursor-pointer pr-2"
            >
              <option value="all">All Layers</option>
              <option value="1">1 Layer</option>
              <option value="2">2 Layers</option>
              <option value="3">3 Layers</option>
              <option value="4">4 Layers</option>
              <option value="5">5 Layers</option>
            </select>
          </div>

          <div className="flex gap-2 w-full sm:w-auto">
            <div className="relative flex-1 sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input
                type="text"
                list="employees"
                placeholder="Enter Employee ID..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  if (nodeMap.has(e.target.value)) {
                      setSelectedRoot(e.target.value);
                  }
                }}
                onBlur={() => {
                    if (nodeMap.has(searchTerm)) {
                        setSelectedRoot(searchTerm);
                    }
                }}
                className="w-full pl-9 pr-4 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 h-[38px]"
              />
              <datalist id="employees">
                {suggestions.map(node => (
                  <option key={node.id} value={node.id} />
                ))}
              </datalist>
            </div>
            <button
              type="submit"
              disabled={!selectedRoot || loading}
              className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors whitespace-nowrap h-[38px] flex items-center justify-center min-w-[80px]"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Build'}
            </button>
          </div>
        </form>
      </div>

      {/* Chart Display Area */}
      <div 
        ref={chartContainerRef}
        className={`flex-1 overflow-hidden bg-slate-50/50 relative flex flex-col items-center justify-center ${
            svgContent ? (isDragging ? 'cursor-grabbing' : 'cursor-grab') : ''
        }`}
