    if (!svgContent) return;
    setIsDragging(true);
    dragStartRef.current = { 
      x: e.clientX - transform.x, 
      y: e.clientY - transform.y 
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setTransform(prev => ({
      ...prev,
      x: e.clientX - dragStartRef.current.x,
      y: e.clientY - dragStartRef.current.y
    }));
  };

  const handleMouseUp = () => setIsDragging(false);

  const zoomIn = () => setTransform(prev => ({ ...prev, scale: Math.min(prev.scale + 0.2, 5) }));
  const zoomOut = () => setTransform(prev => ({ ...prev, scale: Math.max(prev.scale - 0.2, 0.1) }));
  const resetView = () => setTransform({ x: 0, y: 0, scale: 1 });

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      {/* Controls Header */}
      <div className="p-4 border-b border-slate-200 bg-slate-50 flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center z-10">
        <div className="mb-2 xl:mb-0">
          <h3 className="font-semibold text-slate-700 flex items-center gap-2">
            <Network className="w-5 h-5 text-indigo-600" />
            Dynamic Org Chart
          </h3>
          <p className="text-sm text-slate-500">Visualize reporting lines for a specific employee</p>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row flex-wrap gap-3 w-full xl:w-auto items-end sm:items-center">

          <div className="flex items-center gap-3 bg-white px-3 py-2 rounded-lg border border-slate-200 mr-2 shadow-sm">
            <Settings2 className="w-4 h-4 text-slate-400" />
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer select-none">
              <input 
                type="checkbox" 
                checked={showDesignation} 
                onChange={(e) => setShowDesignation(e.target.checked)}
                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4" 
              />
              Designation
            </label>
            <div className="w-px h-4 bg-slate-200 mx-1"></div>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer select-none">
              <input 
                type="checkbox" 
                checked={showGrade} 
                onChange={(e) => setShowGrade(e.target.checked)}
                className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4" 
              />
              Grade
            </label>
          </div>

          <div className="flex items-center gap-2 border border-slate-300 rounded-lg px-2 bg-white h-[38px]">
             <LayoutTemplate className="w-4 h-4 text-slate-400" />
             <select
               value={direction}
               onChange={(e) => setDirection(e.target.value as ChartDirection)}
               className="text-sm bg-transparent focus:outline-none text-slate-700 cursor-pointer pr-1"
               title="Chart Orientation"
             >
               <option value="TD">Top Down</option>
               <option value="BT">Bottom Up</option>
               <option value="LR">Left Right</option>
               <option value="RL">Right Left</option>
             </select>
          </div>

          <div className="flex items-center gap-2 border border-slate-300 rounded-lg px-2 bg-white h-[38px]">
            <Layers className="w-4 h-4 text-slate-400" />
            <select
              value={depthLimit}
              onChange={(e) => setDepthLimit(e.target.value)}
              className="text-sm bg-transparent focus:outline-none text-slate-700 cursor-pointer pr-2"
            >
              <option value="all">All Layers</option>
              <option value="1">1 Layer</option>
              <option value="2">2 Layers</option>
              <option value="3">3 Layers</option>
              <option value="4">4 Layers</option>
              <option value="5">5 Layers</option>
            </select>
          </div>

          <div className="flex gap-2 w-full sm:w-auto">
            <div className="relative flex-1 sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input
                type="text"
                list="employees"
                placeholder="Enter Employee ID..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  if (nodeMap.has(e.target.value)) {
                      setSelectedRoot(e.target.value);
                  }
                }}
                onBlur={() => {
                    if (nodeMap.has(searchTerm)) {
                        setSelectedRoot(searchTerm);
                    }
                }}
                className="w-full pl-9 pr-4 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 h-[38px]"
              />
              <datalist id="employees">
                {suggestions.map(node => (
                  <option key={node.id} value={node.id} />
                ))}
              </datalist>
            </div>
            <button
              type="submit"
              disabled={!selectedRoot || loading}
              className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors whitespace-nowrap h-[38px] flex items-center justify-center min-w-[80px]"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Build'}
            </button>
          </div>
        </form>
      </div>

      {/* Chart Display Area */}
      <div 
        ref={chartContainerRef}
        className={`flex-1 overflow-hidden bg-slate-50/50 relative flex flex-col items-center justify-center ${
            svgContent ? (isDragging ? 'cursor-grabbing' : 'cursor-grab') : ''
        }`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >

        {!svgContent && !loading && (
          <div className="text-center text-slate-400">
            <Network className="w-16 h-16 mx-auto mb-4 opacity-20" />
            <p>Select an employee and configure options above to generate their subtree.</p>
          </div>
