import React, { useState, useRef } from 'react';
import { UploadCloud, Play, FileText, X } from 'lucide-react';
import { ColumnMapping } from '../types';

interface InputSectionProps {
  onProcess: (text: string, mapping?: ColumnMapping) => void;
}

const InputSection: React.FC<InputSectionProps> = ({ onProcess }) => {
  const [text, setText] = useState('');
  const [activeTab, setActiveTab] = useState<'paste' | 'upload'>('paste');

  // Upload State
  const [fileContent, setFileContent] = useState<string>('');
  const [headers, setHeaders] = useState<string[]>([]);
  const [fileName, setFileName] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Mapping State
  const [mapping, setMapping] = useState<ColumnMapping>({
    employee: 0,
    manager: 1,
    name: -1,
    designation: -1,
    grade: -1
  });

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileName(file.name);
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      setFileContent(content);

      // Parse headers (first line)
      const firstLine = content.split('\n')[0];
      if (firstLine) {
        const extractedHeaders = firstLine.split(/,|;/).map(h => h.trim().replace(/^"|"$/g, ''));
        setHeaders(extractedHeaders);

        const lowerHeaders = extractedHeaders.map(h => h.toLowerCase());

        // Helper to find index safely or return default
        const findIndexSafe = (keywords: string[], defaultIdx: number) => {
           const idx = lowerHeaders.findIndex(h => keywords.some(k => h.includes(k)));
           return idx !== -1 ? idx : defaultIdx;
        };

        setMapping({
          employee: findIndexSafe(['employee id', 'email', 'user id', 'emp id', 'id'], 0),
          manager: findIndexSafe(['manager', 'boss', 'report'], 1),
          name: findIndexSafe(['display name', 'full name', 'employee name', 'name'], -1),
          designation: findIndexSafe(['designation', 'title', 'role', 'job'], -1),
          grade: findIndexSafe(['grade', 'level'], -1),
        });
      }
    };
    reader.readAsText(file);
  };

  const handleResetUpload = () => {
    setFileContent('');
    setHeaders([]);
    setFileName('');
    if (fileInputRef.current) fileInputRef.current.value = '';
    // Reset mapping to defaults
    setMapping({ employee: 0, manager: 1, name: -1, designation: -1, grade: -1 });
  };

  const processUpload = () => {
    onProcess(fileContent, mapping);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-lg font-semibold text-slate-800">Data Input</h2>
          <p className="text-sm text-slate-500">
            Import your organization data to visualize hierarchy.
          </p>
        </div>

        <div className="bg-slate-100 p-1 rounded-lg flex gap-1">
           <button 
             onClick={() => setActiveTab('paste')}
             className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all ${activeTab === 'paste' ? 'bg-white shadow text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
           >
             Paste Text
           </button>
           <button 
             onClick={() => setActiveTab('upload')}
             className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all ${activeTab === 'upload' ? 'bg-white shadow text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
           >
             Upload CSV
           </button>
        </div>
      </div>

      {activeTab === 'paste' && (
        <div className="space-y-4">
          <div className="relative">
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder={`alice@acme.com, ceo@acme.com\nbob@acme.com, alice@acme.com\n...`}
