import React, { useState, useMemo } from 'react';
import { TreeData, EmployeeNode } from '../types';
import { ChevronDown, ChevronRight, User, Users, Search, X, Filter } from 'lucide-react';

interface OrgTreeProps {
  data: TreeData[];
  allNodes: EmployeeNode[];
}

const TreeNode: React.FC<{ nodeData: TreeData; depth: number }> = ({ nodeData, depth }) => {
  const [isOpen, setIsOpen] = useState(true);
  const hasChildren = nodeData.children.length > 0;
  const { node } = nodeData;

  const displayLabel = () => {
    // Priority: Name > ID
    let label = node.name || node.id;

    // Add extras
    const extras = [];
    if (node.name) extras.push(node.id); // Show ID if Name is primary
    if (node.grade) extras.push(node.grade);
    if (node.designation) extras.push(node.designation);

    return { main: label, sub: extras.join(' • ') };
  };

  const { main, sub } = displayLabel();

  return (
    <div className="select-none">
      <div 
        className={`
          flex items-center py-2 px-3 rounded-lg cursor-pointer transition-colors
          ${depth === 0 ? 'bg-indigo-50 mb-1 border border-indigo-100' : 'hover:bg-slate-50'}
        `}
        style={{ marginLeft: `${depth * 24}px` }}
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="flex items-center justify-center w-5 h-5 mr-1 text-slate-400">
          {hasChildren && (
            isOpen ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />
          )}
        </div>

        <div className={`p-1.5 rounded-full mr-3 ${depth === 0 ? 'bg-indigo-200 text-indigo-700' : 'bg-slate-200 text-slate-600'}`}>
          {depth === 0 ? <Users className="w-4 h-4" /> : <User className="w-4 h-4" />}
        </div>

        <div className="flex flex-col">
          <span className={`text-sm ${depth === 0 ? 'font-bold text-indigo-900' : 'font-medium text-slate-700'}`}>
            {main}
          </span>
          <span className="text-xs text-slate-500">
             Level {nodeData.node.level} {sub && ` • ${sub}`}
          </span>
        </div>
      </div>

      {isOpen && hasChildren && (
        <div className="border-l border-slate-200 ml-[1.65rem] pl-1">
          {nodeData.children.map((child) => (
            <TreeNode key={child.id} nodeData={child} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
};

const OrgTree: React.FC<OrgTreeProps> = ({ data, allNodes }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredRootId, setFilteredRootId] = useState<string | null>(null);

  // Helper to find a specific node in the recursive structure
  const findSubtree = (nodes: TreeData[], targetId: string): TreeData | null => {
    for (const node of nodes) {
      if (node.id === targetId) return node;
      if (node.children.length > 0) {
        const found = findSubtree(node.children, targetId);
        if (found) return found;
      }
    }
    return null;
  };

  // Determine what to display: Full tree or Filtered Subtree
  const displayData = useMemo(() => {
    if (!filteredRootId) return data;
    const found = findSubtree(data, filteredRootId);
    // If found, return as an array (since OrgTree iterates over a list of roots)
    return found ? [found] : [];
  }, [data, filteredRootId]);

  // Suggestions for autocomplete
  const suggestions = useMemo(() => {
    if (!searchTerm) return [];
    return allNodes
      .filter(n => 
        n.id.toLowerCase().includes(searchTerm.toLowerCase()) || 
        (n.name && n.name.toLowerCase().includes(searchTerm.toLowerCase()))
      )
      .slice(0, 10);
  }, [searchTerm, allNodes]);

  const handleFilter = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;

    // Check if valid ID or Name match
    const foundNode = allNodes.find(n => n.id === searchTerm || n.name === searchTerm);

    if (foundNode) {
      setFilteredRootId(foundNode.id);
    } else {
        // Fallback for typed ID
         const isValid = allNodes.some(n => n.id === searchTerm);
         if (isValid) setFilteredRootId(searchTerm);
    }
  };

  const handleClear = () => {
    setSearchTerm('');
    setFilteredRootId(null);
  };

  if (allNodes.length === 0) return null;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      {/* Header with Filter Controls */}
      <div className="p-4 border-b border-slate-200 bg-slate-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h3 className="font-semibold text-slate-700 flex items-center gap-2">
            <Users className="w-5 h-5 text-indigo-600" />
            Hierarchy Visualization
          </h3>
          <p className="text-sm text-slate-500">
             {filteredRootId ? `Viewing subtree for ${filteredRootId}` : 'Viewing full organization structure'}
          </p>
        </div>

        <form onSubmit={handleFilter} className="flex items-center gap-2 w-full sm:w-auto">
           <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input
              type="text"
              list="tree-employees"
              placeholder="Filter by name or ID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-8 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <datalist id="tree-employees">
              {suggestions.map(node => (
                <option key={node.id} value={node.id}>{node.name}</option>
              ))}
            </datalist>

            {searchTerm && (
              <button 
                type="button"
                onClick={() => setSearchTerm('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
              >
                <X className="w-4 h-4" />
              </button>
            )}
           </div>

           {filteredRootId ? (
             <button
                type="button"
                onClick={handleClear}
                className="px-3 py-2 bg-white border border-slate-300 text-slate-700 text-sm font-medium rounded-lg hover:bg-slate-50 transition-colors flex items-center gap-2"
             >
                <X className="w-4 h-4" />
                Reset
             </button>
           ) : (
             <button
                type="submit"
                disabled={!searchTerm}
                className="px-3 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
             >
                <Filter className="w-4 h-4" />
                Filter
             </button>
           )}
        </form>
      </div>

      {/* Tree Content */}
      <div className="p-6 h-full overflow-auto flex-1">
        {displayData.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-400">
             <Search className="w-12 h-12 mb-2 opacity-20" />
             <p>No matches found in the hierarchy.</p>
             <button onClick={handleClear} className="mt-4 text-indigo-600 hover:underline text-sm">
               Show full tree
             </button>
          </div>
        ) : (
          <div className="space-y-2">
            {displayData.map((root) => (
              <TreeNode key={root.id} nodeData={root} depth={0} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

