import { EmployeeNode, RawRow, TreeData, ColumnMapping } from '../types';

// Helper: Cleans text from mobile artifacts (BOM, Smart Quotes, Line Endings)
export const cleanCSVText = (text: string): string => {
  return text
    // Remove Byte Order Mark (BOM) common in Excel/Mobile CSVs
    .replace(/^\uFEFF/, '') 
    // Normalize Smart/Curly Quotes
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    // Normalize Line Endings
    .replace(/\r\n|\r/g, '\n');
};

// Helper: Splits a single CSV line into columns, respecting quotes
export const splitCSVLine = (line: string): string[] => {
  // Detect delimiter: if line has semicolon and no comma, use semicolon. Otherwise default to comma.
  const hasSemi = line.includes(';');
  const hasComma = line.includes(',');

  // Regex matches a delimiter only if it's NOT inside quotes
  const delimiter = (hasSemi && !hasComma) ? /;(?=(?:(?:[^"]*"){2})*[^"]*$)/ : /,(?=(?:(?:[^"]*"){2})*[^"]*$)/;

  return line.split(delimiter).map((s) => s.trim().replace(/^"|"$/g, ''));
};

export const parseCSV = (text: string, mapping?: ColumnMapping): RawRow[] => {
  const normalizedText = cleanCSVText(text);
  const lines = normalizedText.split('\n').map((line) => line.trim()).filter((line) => line.length > 0);

  const startIndex = mapping ? 1 : 0;

  return lines.slice(startIndex).map((line): RawRow | null => {
    const parts = splitCSVLine(line);

    if (mapping) {
      // Validate bounds - only Employee column is strictly required
      if (parts.length <= mapping.employee) return null;

      const emp = parts[mapping.employee];
      // Manager might be empty or missing index
      const mgr = parts[mapping.manager];

      // Ensure mandatory Employee field has data
      if (!emp) return null;

      // If manager is missing/empty, default to Self (indicates Root)
      const finalMgr = mgr || emp;

      return {
        employee: emp,
        manager: finalMgr,
        name: mapping.name !== -1 ? parts[mapping.name] : undefined,
        designation: mapping.designation !== -1 ? parts[mapping.designation] : undefined,
        grade: mapping.grade !== -1 ? parts[mapping.grade] : undefined,
      };
    } else {
      // Legacy mode: Col 0 = Employee, Col 1 = Manager
      if (parts.length < 1) return null;
      const emp = parts[0];
      const mgr = parts[1];

      if (!emp) return null;

      return {
        employee: emp,
        manager: mgr || emp,
      };
    }
  })
  .filter((row): row is RawRow => row !== null);
};

export const processOrgData = (rows: RawRow[]): { nodes: EmployeeNode[]; roots: string[] } => {
  const managerMap = new Map<string, string>();
  const metaDataMap = new Map<string, { designation?: string; grade?: string; name?: string }>();
  const allEmployees = new Set<string>();

  // 1. Build Adjacency Map and Metadata Map
  rows.forEach((row) => {
    if (row.employee && row.manager) {
      managerMap.set(row.employee, row.manager);
      allEmployees.add(row.employee);
      allEmployees.add(row.manager);

      // Store metadata for the employee
      metaDataMap.set(row.employee, { 
        designation: row.designation, 
        grade: row.grade,
        name: row.name
      });
    }
  });

  const processedCache = new Map<string, EmployeeNode>();

  // Helper to build chain recursively
  const buildNode = (empId: string, visited: Set<string>): EmployeeNode => {
    if (processedCache.has(empId)) {
      return processedCache.get(empId)!;
    }

    const meta = metaDataMap.get(empId) || {};

    // Cycle detection
    if (visited.has(empId)) {
      return {
        id: empId,
        name: meta.name,
        managerId: managerMap.get(empId) || null,
        level: -1,
        rootId: 'ERROR: CYCLE',
        chain: [],
        directReports: [],
        hasCycle: true,
        designation: meta.designation,
        grade: meta.grade,
      };
    }

    const managerId = managerMap.get(empId);

    // Base case: No manager found in map, or manager is self (Root)
    if (!managerId || managerId === empId) {
      const node: EmployeeNode = {
        id: empId,
        name: meta.name,
        managerId: managerId || null,
        level: 0,
        rootId: empId,
        chain: [empId],
        directReports: [],
        hasCycle: false,
        designation: meta.designation,
        grade: meta.grade,
      };
      processedCache.set(empId, node);
      return node;
    }

    // Recursive step
    const newVisited = new Set(visited);
    newVisited.add(empId);
    const parentNode = buildNode(managerId, newVisited);

    if (parentNode.hasCycle) {
       // Propagate error
       const node: EmployeeNode = {
        id: empId,
        name: meta.name,
        managerId,
        level: -1,
        rootId: 'ERROR: CYCLE',
        chain: [],
        directReports: [],
        hasCycle: true,
        designation: meta.designation,
        grade: meta.grade,
      };
      processedCache.set(empId, node);
      return node;
    }

    const node: EmployeeNode = {
      id: empId,
      name: meta.name,
      managerId,
      level: parentNode.level + 1,
      rootId: parentNode.rootId,
      chain: [...parentNode.chain, empId],
      directReports: [],
      hasCycle: false,
      designation: meta.designation,
      grade: meta.grade,
    };
    processedCache.set(empId, node);
    return node;
  };

  // 2. Build all nodes
  allEmployees.forEach((empId) => {
    buildNode(empId, new Set());
  });

  // 3. Populate Direct Reports
  const finalNodes = Array.from(processedCache.values());
  finalNodes.forEach(node => {
    if (node.managerId && node.managerId !== node.id) {
      const managerNode = processedCache.get(node.managerId);
      if (managerNode) {
        managerNode.directReports.push(node.id);
      }
    }
  });

  // 4. Identify Roots (Level 0)
  const roots = finalNodes.filter(n => n.level === 0).map(n => n.id);

  return { nodes: finalNodes.sort((a, b) => a.level - b.level), roots };
};

export const buildTreeData = (rootIds: string[], nodes: EmployeeNode[]): TreeData[] => {
  const nodeMap = new Map(nodes.map(n => [n.id, n]));

  const buildTree = (id: string): TreeData => {
    const node = nodeMap.get(id)!;
    const children = node.directReports
      .map(childId => buildTree(childId))
      .sort((a, b) => {
        // Sort by Name if available, else ID
        const nameA = a.node.name || a.id;
        const nameB = b.node.name || b.id;
        return nameA.localeCompare(nameB);
      });

    return {
      id,
      node,
      children
    };
  };

  return rootIds.map(id => buildTree(id));
};

