// Helper: Cleans text from mobile artifacts (BOM, Smart Quotes, Line Endings)
export const cleanCSVText = (text: string): string => {
  return text
    // Remove Byte Order Mark (BOM) common in Excel/Mobile CSVs
    .replace(/^\uFEFF/, '') 
    // Normalize Smart/Curly Quotes
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    // Normalize Line Endings
    .replace(/\r\n|\r/g, '\n');
};

// Helper: Detects whether comma or semicolon is the likely delimiter
export const detectDelimiter = (line: string): RegExp => {
  const commas = (line.match(/,/g) || []).length;
  const semis = (line.match(/;/g) || []).length;

  // Prefer Semicolon if it appears more often than comma, or if there are no commas
  // This helps with "European" CSVs that might contain commas in text fields
  if (semis > commas) {
    return /;(?=(?:(?:[^"]*"){2})*[^"]*$)/;
  }

  // Default to comma
  return /,(?=(?:(?:[^"]*"){2})*[^"]*$)/;
};

// Helper: Splits a single CSV line into columns, respecting quotes
export const splitCSVLine = (line: string, delimiter?: RegExp): string[] => {
  // If no delimiter provided, detect it from this specific line (less reliable for mixed content)
  const delimRegex = delimiter || detectDelimiter(line);
  return line.split(delimRegex).map((s) => s.trim().replace(/^"|"$/g, ''));
};

export const parseCSV = (text: string, mapping?: ColumnMapping): RawRow[] => {
  const normalizedText = cleanCSVText(text);
  const lines = normalizedText.split('\n').map((line) => line.trim()).filter((line) => line.length > 0);

  if (lines.length === 0) return [];

  // Detect delimiter from the first line (usually headers) and enforce it for all rows
  // This prevents issues where a data row has extra commas (in quotes) that might confuse the detector if run per-line
  const globalDelimiter = detectDelimiter(lines[0]);

  const startIndex = mapping ? 1 : 0;

  return lines.slice(startIndex).map((line): RawRow | null => {
    const parts = splitCSVLine(line, globalDelimiter);

    if (mapping) {
      // Validate bounds - only Employee column is strictly required
      if (parts.length <= mapping.employee) return null;

      const emp = parts[mapping.employee];
      // Manager might be empty or missing index
      const mgr = parts[mapping.manager];

      // Ensure mandatory Employee field has data
      if (!emp) return null;

      // If manager is missing/empty, default to Self (indicates Root)
      const finalMgr = mgr || emp;

      return {
        employee: emp,
        manager: finalMgr,
        name: mapping.name !== -1 ? parts[mapping.name] : undefined,
        designation: mapping.designation !== -1 ? parts[mapping.designation] : undefined,
        grade: mapping.grade !== -1 ? parts[mapping.grade] : undefined,
      };
    } else {
      // Legacy mode: Col 0 = Employee, Col 1 = Manager
      if (parts.length < 1) return null;
      const emp = parts[0];
      const mgr = parts[1];

      if (!emp) return null;

      return {
        employee: emp,
        manager: mgr || emp,
      };
    }
  })
  .filter((row): row is RawRow => row !== null);
};

