import React, { useState, useRef } from 'react';
import { UploadCloud, Play, FileText, X } from 'lucide-react';
import { ColumnMapping } from '../types';
import { cleanCSVText, splitCSVLine } from '../services/orgProcessor';

interface InputSectionProps {
  onProcess: (text: string, mapping?: ColumnMapping) => void;
}

const InputSection: React.FC<InputSectionProps> = ({ onProcess }) => {
  const [text, setText] = useState('');
  const [activeTab, setActiveTab] = useState<'paste' | 'upload'>('paste');

  // Upload State
  const [fileContent, setFileContent] = useState<string>('');
  const [headers, setHeaders] = useState<string[]>([]);
  const [fileName, setFileName] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Mapping State
  const [mapping, setMapping] = useState<ColumnMapping>({
    employee: 0,
    manager: 1,
    name: -1,
    designation: -1,
    grade: -1
  });

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileName(file.name);
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      setFileContent(content);

      // Use the shared cleaner from orgProcessor
      const normalizedContent = cleanCSVText(content);

      // Parse headers (first line)
      const firstLine = normalizedContent.split('\n')[0];

      if (firstLine) {
        // Use the shared splitter to ensure headers match data parsing logic
        const extractedHeaders = splitCSVLine(firstLine);
        setHeaders(extractedHeaders);

        const lowerHeaders = extractedHeaders.map(h => h.toLowerCase());

        // Helper to find index safely or return default
        const findIndexSafe = (keywords: string[], defaultIdx: number) => {
           const idx = lowerHeaders.findIndex(h => keywords.some(k => h.includes(k)));
           return idx !== -1 ? idx : defaultIdx;
        };

        setMapping({
          employee: findIndexSafe(['employee id', 'email', 'user id', 'emp id', 'id'], 0),
          manager: findIndexSafe(['manager', 'boss', 'report'], 1),
          name: findIndexSafe(['display name', 'full name', 'employee name', 'name'], -1),
          designation: findIndexSafe(['designation', 'title', 'role', 'job'], -1),
          grade: findIndexSafe(['grade', 'level'], -1),
        });
      }
    };
    reader.readAsText(file);
  };

  const handleResetUpload = () => {
    setFileContent('');
    setHeaders([]);
    setFileName('');
    if (fileInputRef.current) fileInputRef.current.value = '';
    // Reset mapping to defaults
    setMapping({ employee: 0, manager: 1, name: -1, designation: -1, grade: -1 });
  };

  const processUpload = () => {
    onProcess(fileContent, mapping);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-lg font-semibold text-slate-800">Data Input</h2>
          <p className="text-sm text-slate-500">
            Import your organization data to visualize hierarchy.
          </p>
        </div>

        <div className="bg-slate-100 p-1 rounded-lg flex gap-1">
           <button 
             onClick={() => setActiveTab('paste')}
             className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all ${activeTab === 'paste' ? 'bg-white shadow text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
           >
             Paste Text
           </button>
           <button 
             onClick={() => setActiveTab('upload')}
             className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all ${activeTab === 'upload' ? 'bg-white shadow text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
           >
             Upload CSV
           </button>
        </div>
      </div>

      {activeTab === 'paste' && (
        <div className="space-y-4">
          <div className="relative">
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder={`alice@acme.com, ceo@acme.com\nbob@acme.com, alice@acme.com\n...`}
              className="w-full h-32 p-4 font-mono text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none resize-none bg-slate-50"
            />
            <div className="absolute bottom-4 right-4 text-xs text-slate-400">
              {text.split('\n').filter(l => l.trim()).length} rows
            </div>
          </div>
          <div className="flex justify-end">
            <button
              onClick={() => onProcess(text)}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors shadow-sm"
            >
              <Play className="w-4 h-4" />
              Process Data
            </button>
          </div>
        </div>
      )}

      {activeTab === 'upload' && (
        <div className="space-y-6">
          {!fileContent ? (
            <div className="border-2 border-dashed border-slate-300 rounded-lg p-8 text-center hover:bg-slate-50 transition-colors">
              <input 
                type="file" 
                accept=".csv,.txt"
                onChange={handleFileUpload}
                ref={fileInputRef}
                className="hidden"
                id="file-upload"
              />
              <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-3">
                <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center">
                  <UploadCloud className="w-6 h-6" />
                </div>
                <span className="text-sm font-medium text-slate-700">Click to upload CSV</span>
                <span className="text-xs text-slate-500">First row must contain headers</span>
              </label>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="flex items-center justify-between bg-indigo-50 px-4 py-3 rounded-lg border border-indigo-100">
                <div className="flex items-center gap-3">
                  <FileText className="w-5 h-5 text-indigo-600" />
                  <div>
                    <p className="text-sm font-medium text-indigo-900">{fileName}</p>
                    <p className="text-xs text-indigo-600">{headers.length} columns detected</p>
                  </div>
                </div>
                <button onClick={handleResetUpload} className="text-indigo-400 hover:text-indigo-700">
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 border-t border-slate-100 pt-4">
                 <div>
                   <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Employee ID (Required)</label>
                   <select 
                     value={mapping.employee}
                     onChange={(e) => setMapping({...mapping, employee: parseInt(e.target.value)})}
                     className="w-full p-2 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 outline-none"
                   >
                     {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                   </select>
                 </div>
                 <div>
                   <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Manager ID (Required)</label>
                   <select 
                     value={mapping.manager}
                     onChange={(e) => setMapping({...mapping, manager: parseInt(e.target.value)})}
                     className="w-full p-2 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 outline-none"
                   >
                     {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                   </select>
                 </div>

                 <div>
                   <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Employee Name (Optional)</label>
                   <select 
                     value={mapping.name}
                     onChange={(e) => setMapping({...mapping, name: parseInt(e.target.value)})}
                     className="w-full p-2 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 outline-none"
                   >
                     <option value={-1}>-- Ignore --</option>
                     {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                   </select>
                 </div>

                 <div>
                   <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Job Title (Optional)</label>
                   <select 
                     value={mapping.designation}
                     onChange={(e) => setMapping({...mapping, designation: parseInt(e.target.value)})}
                     className="w-full p-2 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 outline-none"
                   >
                     <option value={-1}>-- Ignore --</option>
                     {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                   </select>
                 </div>

                 <div>
                   <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Grade/Level (Optional)</label>
                   <select 
                     value={mapping.grade}
                     onChange={(e) => setMapping({...mapping, grade: parseInt(e.target.value)})}
                     className="w-full p-2 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 outline-none"
                   >
                     <option value={-1}>-- Ignore --</option>
                     {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                   </select>
                 </div>
              </div>

              <div className="flex justify-end pt-2">
                <button
                  onClick={processUpload}
                  className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors shadow-sm"
                >
                  <Play className="w-4 h-4" />
                  Process Data
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

